-- Generated by tools/reference/import-catalogs.cs from pinned source files: change that script, not this file.
-- Interactions between two drug ingredients (RxNorm codes, the lower first), each with DDInter's level.
-- From DDInter 2.0 (https://ddinter2.scbdd.com), licensed CC BY-NC-SA 4.0: see LICENSE.md in this folder. Not for commercial use.
-- Applied as ehr_owner after db/policies; safe to run again. Sources, versions, licenses and attribution:
-- docs/expansion/reference-data.md. The rows are COPY blocks, as pg_dump writes them: psql loads the file as it
-- stands, and the tests' database through tests/Ehr.Testing/ReferenceData.cs. Tab-separated; \N is a null.
BEGIN;
CREATE TEMPORARY TABLE incoming_drug_interactions (ingredient_a text, ingredient_b text, level text) ON COMMIT DROP;
SELECT ingredient_a, ingredient_b, level FROM incoming_drug_interactions
ON CONFLICT (ingredient_a, ingredient_b) DO UPDATE
    SET level = EXCLUDED.level
    WHERE (drug_interactions.level)
        IS DISTINCT FROM (EXCLUDED.level);
DELETE FROM ehr.drug_interactions t
WHERE NOT EXISTS (SELECT 1 FROM incoming_drug_interactions i WHERE i.ingredient_a = t.ingredient_a AND i.ingredient_b = t.ingredient_b);
COMMIT;
